Translate("ruRU", "loch-modan", {
	title = "Лок Модан",
	sections = {
		{
			title = "Обзор",
			text = [=[Лок Модан — широкая котловина холмов и сосновых лесов в краю Каз Модан, к востоку от {link:dun-morogh}Дун Морога{/link}. В сердце ее лежит {link:the-loch}Озеро Лок{/link}, великое озеро, давшее земле имя; на северном конце его сдерживает {link:stonewrought-dam}Каменная Плотина{/link}. Городок {link:thelsamar}Телсамар{/link} стоит близ его западного берега. Башни дворфов стерегут перевалы, ведущие на запад в {link:ironforge}Стальгорн{/link}, на север в {link:wetlands}Болотину{/link} и на юг, к {link:searing-gorge}Тлеющему ущелью{/link}. Это край мягче снегов Дун Морога, богатый рудой, дичью и рыбой, и {link:dwarves}дворфы{/link} {link:kingdom-of-ironforge}королевства Стальгорн{/link} издавна считают его своим.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не говорит, когда {link:dwarves}дворф{/link}ы впервые поселились на берегах озера и когда была возведена {link:stonewrought-dam}Каменная Плотина{/link}. В их истории эта земля стара. В Долине Королей две {link:ogres}огр{/link}омные статуи стоят на страже южной дороги. Они чтят двух вождей — Мадорана Бронзоборода и Кардроса Неистового Молота, которые вели свои кланы в эпоху Войны Трех Молотов. Рассказывают, что их сыновья воздвигли статуи после той войны, чтобы они смотрели за дорогой на юг — как предостережение всякому, кто вновь пойдет на владения дворфов.]=],
		},
		{
			title = "Наши дни",
			text = [=[Лок Модан — земля в осаде, и защитников у нее мало. Резерв {link:ironforge}Стальгорн{/link}а отозван сражаться за {link:alliance}Альянс{/link} на дальних рубежах, а обещанное озерному краю подкрепление так и не пришло. {link:captain-rugelfuss}Капитан Ругельфусс{/link} держит Долину Королей одним-единственным полком, пока {link:troggs}трогги{/link} племени Камнедробов валом валят из южных холмов и захватывают раскопки Лиги исследователей у озера. {link:ogres}Огры{/link} клана {link:mo-grosh-ogres}Мо'грош{/link} совершают набеги с северо-востока. {link:kobolds}Кобольды{/link} заняли {link:silver-stream-mine}Рудник у Серебряного ручейка{/link}. Хуже всего то, что диверсанты {link:dark-iron-dwarves}Черного Железа{/link} подобрались к самой плотине, и у них есть друзья среди тех, кому {link:dwarves}дворф{/link}ы доверяют. В {link:thelsamar}Телсамар{/link}е магистрату {link:magistrate-bluntnose}Тупонос{/link}у сказали, что горстку солдат ему придется ждать месяцами. Он перестал ждать и платит звонкой монетой любому чужаку, который готов сражаться.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:dwarves}Дворфы{/link} {link:ironforge}Стальгорн{/link}а.{/b} {link:gorn}Горн{/link}ые пехотинцы, рудокопы, рыбаки и повара живут в {link:thelsamar}Телсамар{/link}е и несут службу в башнях вдоль перевалов.
• {b}Лига исследователей.{/b} Из своего отделения в Телсамаре {link:explorers-league}Лига исследователей{/link} снабжает раскопки, которые ведет геолог {link:prospector-ironband}Сталекрут{/link} среди руин к востоку от озера.
• {b}Охотники Приюта Странников.{/b} Дворфы, люди и высшая эльфийка держат охотничий приют в восточных холмах.
• {b}{link:stonesplinter-troggs}Трогги Камнедробов{/link}.{/b} Они удерживают южные долины, острова озера и руины раскопок.
• {b}{link:mo-grosh-ogres}Огры Мо'грош{/link}.{/b} Клан {link:ogres}огров{/link} устроил свой оплот в пещерах северо-востока.
• {b}{link:tunnel-rat-kobolds}Кобольды Туннельной Крысы{/link}.{/b} {link:kobolds}Кобольды{/link} вырыли логова в западных предгорьях и заполнили {link:silver-stream-mine}Рудник у Серебряного ручейка{/link}.
• {b}{link:dark-iron-dwarves}Дворфы Черного Железа{/link}.{/b} Саперы и мятежники рыщут вокруг плотины, и по меньшей мере один их лазутчик прятался среди носильщиков самих дворфов.]=],
		},
		{
			title = "История",
			text = [=[• {b}Три Молота.{/b} После войны трех кланов королей кланов Бронзобородов и Неистового Молота увековечили в камне у южных ворот озерного края.
• {b}Вторая война.{/b} Когда {link:horde}Орда{/link} захватила Каз Модан во {link:second-war}Вторую войну{/link}, озерный край оказался под властью {link:orcs}орк{/link}ов. {link:dwarves}Дворфы{/link} отвоевали его, но обломки орочьих катапульт и повозок до сих пор лежат на отмелях и за старым серебряным рудником.
• {b}Раскопки.{/b} {link:explorers-league}Лига исследователей{/link} начала раскопки среди древних руин к юго-востоку от озера. Ее землекопы нашли странных резных идолов, и вскоре после этого из-под земли вышли {link:troggs}трогг{/link}и.
• {b}Наши дни.{/b} Теперь озерный край стерегут те немногие, кто остался, и любая помощь, какую они могут нанять.]=],
		},
		{
			title = "Предания озера",
			text = [=[• {link:thelsamar}Телсамар{/link} славится кровяными колбасками: медвежье мясо, набитое в кабаньи кишки и приправленное ихором пауков. Повариха уверяет, что это труднее, чем кажется.
• Кроколисков озера ценят за шкуры и мясо, но они окопались на островах, и мало кто из охотников одолевает их, не получив шрама.
• {link:gorn}Горн{/link}ые пехотинцы озерного края пьют Мерцающее Крепкое, которое варят в далеком Поселке Пивоваров. Один отведавший клялся, что от него руки и ноги стали такими легкими, что ему казалось, будто он может летать.
• В Южных вратах снег лежит круглый год, хотя берега озера внизу зелены.]=],
		},
	},
})

Translate("ruRU", "thelsamar", {
	title = "Телсамар",
	aliases = { "Таверна «Крепкое пойло»" },
	sections = {
		{
			title = "Обзор",
			text = [=[Телсамар — главный городок {link:loch-modan}Лок Модан{/link}а, горстка каменных домов близ западного берега озера. Его сердце — Таверна «Крепкое пойло», и в городке никогда нет недостатка в голодных работниках и бегающих детях. Здесь есть кузница, гнездовье грифонов и отделение {link:explorers-league}Лиги исследователей{/link}, а на улице висит объявление о розыске вождя {link:ogres}огр{/link}ов. {link:mountaineer-kadrell}Горный пехотинец Кадрелл{/link} обходит дорогу, ведущую через городок, а магистрат {link:magistrate-bluntnose}Тупонос{/link} следит в нем за порядком. Телсамару недостает многих удобств {link:ironforge}Стальгорн{/link}а: его кузнецу вечно не хватает бронзы, и он мечтает, чтобы какой-нибудь торговец привез в город уголь.]=],
		},
	},
})

Translate("ruRU", "stonewrought-dam", {
	title = "Каменная Плотина",
	sections = {
		{
			title = "Обзор",
			text = [=[Каменная Плотина замыкает северный конец озера — стена из камня {link:dwarves}дворф{/link}ов, столь {link:ogres}огр{/link}омная, что на нее опирается само озеро. Ее хранит главный инженер {link:chief-engineer-hinderweir-vii}Хиндервейр{/link} VII с несколькими инженерами и горными пехотинцами. Большую часть ее стражи отправили на фронт, в том числе главного смотрителя. Потеря ощутима. Дворфы {link:dark-iron-dwarves}Черного Железа{/link} уже разрушили {link:thandol-span}Мост Тандола{/link} и разграбили {link:dun-modr}Дун Модр{/link} на севере, и Хиндервейр уверен, что следующей будет плотина. Их саперов видели на ее восточном скате.]=],
		},
	},
})

Translate("ruRU", "algaz-station", {
	title = "Станция Альгаз",
	aliases = { "северная сторожевая башня" },
	sections = {
		{
			title = "Обзор",
			text = [=[Станция Альгаз — северный сторожевой пост {link:loch-modan}Лок Модан{/link}а. Ее башня стоит там, где туннель Северных врат спускается из {link:dun-morogh}Дун Морога{/link}, чуть южнее перевала {link:dun-algaz}Дун Альгаз{/link}, который ведет дальше, в {link:wetlands}Болотину{/link}. Здесь несут службу многие горные пехотинцы. С вершины башни горный пехотинец Штормпайк следит за дорогами и охотно рассказывает о собственных подвигах. Гарнизону служат бронник и странствующий торговец. К северу от станции горные пехотинцы, стерегущие Дун Альгаз, обнаружили, что дорога впереди кишит {link:orcs}орк{/link}ами.]=],
		},
	},
})

Translate("ruRU", "silver-stream-mine", {
	title = "Рудник у Серебряного ручейка",
	sections = {
		{
			title = "Обзор",
			text = [=[Рудник у Серебряного ручейка лежит на севере {link:loch-modan}Лок Модан{/link}а, между Станцией Альгаз и плотиной. Он много лет давал {link:dwarves}дворф{/link}ам серебро, пока не иссяк. Тогда Лига горняков превратила его в склад и заполнила ящиками с добротным инструментом дворфов. Теперь туда вселились {link:tunnel-rat-kobolds}кобольды Туннельной Крысы{/link} и наложили лапы на все. {link:gorn}Горн{/link}ые пехотинцы намерены очистить рудник, но лига хотела бы, чтобы сперва вынесли ее снаряжение, пока солдаты его не переломали.]=],
		},
	},
})

Translate("ruRU", "ironband-s-excavation-site", {
	title = "Раскопки Сталекрута",
	aliases = { "Раскопки геолога Сталекрута" },
	sections = {
		{
			title = "Обзор",
			text = [=[Раскопки Сталекрута — раскопки {link:explorers-league}Лиги исследователей{/link} среди древних руин к юго-востоку от озера. Ими руководит геолог {link:prospector-ironband}Сталекрут{/link}, а работами заведует {link:magmar-fellhew}Магмар Лесоруб{/link}. Землекопы едва успели откопать великое множество резных каменных идолов, как в руинах вышли на поверхность {link:stonesplinter-troggs}трогги Камнедробов{/link} и прогнали их. Идолы, похоже, притягивают {link:troggs}трогг{/link}ов и некоторых из них приводят в неистовство. Землекопы бежали так быстро, что бросили большую часть инструмента. Теперь раскопками правят вождь троггов и его шаман.]=],
		},
	},
})

Translate("ruRU", "mo-grosh-stronghold", {
	title = "Оплот Мо'грош",
	sections = {
		{
			title = "Обзор",
			text = [=[Оплот Мо'грош — гнездо пещер в холмах к северо-востоку от озера. Клан {link:ogres}огр{/link}ов устроил там свой лагерь, и оттуда они бьют и по {link:thelsamar}Телсамар{/link}у, и по плотине, и по раскопкам. В пещерах они добывают редкие кристаллы. Не так давно они напали из засады на караван с рудой, шедший из {link:wetlands}Болотины{/link}, и унесли руду в свой лагерь. Их вождя, огра {link:chok-sul}Чок'сул{/link}а, разыскивает магистрат Телсамара.]=],
		},
	},
})

Translate("ruRU", "the-farstrider-lodge", {
	title = "Приют Странников",
	aliases = { "приют Странников" },
	sections = {
		{
			title = "Обзор",
			text = [=[Приют Странников стоит в восточных холмах {link:loch-modan}Лок Модан{/link}а. Его высокие балки и широкие крыши — эльфийского стиля, и ни одна летопись не говорит, кто его построил. Сегодня это приют охотников, где охотничье мастерство ценят превыше всего. {link:marek-ironheart}Марек Железное Сердце{/link} торгует там шкурами и мясом кроколисков. Высшая эльфийка {link:vyrin-swiftwind}Вирин Быстрый Ветер{/link} держится особняком, а молодой человек по имени {link:daryl-the-youngling}Дэрил{/link} хвастается перед всяким, кто готов слушать. Торговцы продают луки и ружья тем, кто приходит охотиться.]=],
		},
	},
})

Translate("ruRU", "valley-of-kings", {
	title = "Долина Королей",
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Королей — юго-западный угол {link:loch-modan}Лок Модан{/link}а, где дорога из Южных врат спускается в зелень. Две {link:ogres}огр{/link}омные статуи королей {link:dwarves}дворф{/link}ов — Мадорана Бронзоборода и Кардроса Неистового Молота — стоят над долиной и смотрят на юг. Рядом высится южная сторожевая башня, где служит капитан {link:captain-rugelfuss}Ругельфусс{/link}, чей полк не смеет покинуть пост из страха перед вторжением. Дальше к югу запертые ворота ведут к {link:searing-gorge}Тлеющему ущелью{/link}, и горный пехотинец {link:mountaineer-pebblebitty}Галькогрыз{/link} открывает их лишь тем, кто докажет, чего стоит.]=],
		},
	},
})

Translate("ruRU", "the-loch", {
	title = "Озеро Лок",
	aliases = { "озеро Лок" },
	sections = {
		{
			title = "Обзор",
			text = [=[Озеро Лок — великое озеро края Каз Модан, тихое и холодное под холмами. Рыбаки трудятся на его западном берегу, а охотники ищут кроколисков, окопавшихся на его островах. В его глубинах плавают трешадоны. Острова небезопасны: самый большой из них удерживают {link:troggs}трогг{/link}и, и они набросились на летчика-{link:gnomes}гном{/link}а, который рухнул в воду неподалеку. Старые обломки рассеяны по отмелям, и рыбаки до сих пор находят среди них потерянные вещи.]=],
		},
	},
})

Translate("ruRU", "grizzlepaw-ridge", {
	title = "Хребет Седых Лап",
	sections = {
		{
			title = "Обзор",
			text = [=[Хребет Седых Лап поднимается к югу от {link:thelsamar}Телсамар{/link}а, между городком и землями {link:troggs}трогг{/link}ов на юго-западе. Он принадлежит медведям. Их берлоги разбросаны по склонам, и среди них залег черный медведь {link:ogres}огр{/link}омного роста, {link:ol-sooty}Старина Копотун{/link}, которого охотники Приюта Странников давно и безуспешно пытаются добыть. Путники на дороге внизу поглядывают на холмы, ибо старый медведь порой спускается.]=],
		},
	},
})

Translate("ruRU", "stonesplinter-valley", {
	title = "Долина Камнедробов",
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Камнедробов вьется среди гор на юго-западе {link:loch-modan}Лок Модан{/link}а, и она дала имя {link:troggs}трогг{/link}ам, которые теперь ее заполонили. Их разведчики следят за дорогой, их провидцы и черепобои держат южные холмы, а их вождь {link:grawmug}Гравмуг{/link} не покидает самой глубокой из их пещер. {link:gorn}Горн{/link}ые пехотинцы, которые обходят эти места дозором, возвращаются не всегда. Именно сюда отправилась горный пехотинец {link:mountaineer-ylva}Ильва{/link} искать один такой пропавший дозор, и здесь она пала.]=],
		},
	},
})

Translate("ruRU", "south-gate-pass", {
	title = "Южные врата",
	sections = {
		{
			title = "Обзор",
			text = [=[Южные врата — южный туннель между {link:dun-morogh}Дун Морогом{/link} и {link:loch-modan}Лок Модан{/link}ом. Он идет от башни Форта у Южных врат на западе до Долины Королей на востоке, и это кратчайшая дорога из {link:ironforge}Стальгорн{/link}а в {link:thelsamar}Телсамар{/link}. Проход лежит высоко, и снег скапливается в нем круглый год. Один шаман озерного края послал за кувшином этого снега — для обряда, которого не объяснил. {link:gorn}Горн{/link}ые пехотинцы несут через туннель бочонки стаута из Дун Морога.]=],
		},
	},
})

Translate("ruRU", "captain-rugelfuss", {
	title = "Капитан Ругельфусс",
	subtitle = "Капитан южной башни",
	found = "Южная сторожевая башня, Долина Королей",
	hint = [=[Поговорите с капитаном, который держит южную сторожевую башню.]=],
	allegiance = "Королевство Стальгорн · Горные пехотинцы Стальгорна",
	aliases = { "Ругельфусс" },
	sections = {
		{
			title = "Обзор",
			text = [=[Капитан Ругельфусс командует полком, который стережет южные ворота {link:loch-modan}Лок Модан{/link}а, в башне под статуями Долины Королей. На отдание чести у него нет терпения. {link:alliance}Альянс{/link}у тяжело приходится на чужбине, говорит он, и оттого земли {link:dwarves}дворф{/link}ов тем драгоценнее, а {link:troggs}трогг{/link}и, которые лезут из этих земель, — грозная опасность для короля.]=],
		},
		{
			title = "Значение",
			text = [=[Ругельфусс — солдат, которого оставили держать дверь. Резерв {link:ironforge}Стальгорн{/link}а отозван на фронт, а его немногие горные пехотинцы не могут покинуть ворота, не открыв путь вторжению. Потому он сражается с {link:troggs}трогг{/link}ами единственным оставшимся ему способом: посылает в холмы добровольцев вместо себя.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он держит южные ворота {link:loch-modan}Лок Модан{/link}а с малой долей тех солдат, которые для этого нужны.
• Он направляет своих горных пехотинцев — Кремнебоя, Гравийную Пасть и Стенолома — в долгой войне с {link:troggs}трогг{/link}ами Камнедробов.
• Он узнаёт имя вождя, который ведет восстание троггов.]=],
		},
	},
	chapters = {
		{
			title = "Каменные зубы",
			hint = [=[Принесите капитану доказательство того, что трогги в холмах убиты.]=],
			text = [=[Привязанный к своим воротам, Ругельфусс не мог сам понести войну в холмы. Вместо этого он просил доказательств: каменных зубов {link:troggs}трогг{/link}ов, убитых за его стенами. Каждый зуб, положенный на его стол, означал, что в долине одним троггом меньше, и был малым знаком того, что {link:dwarves}дворф{/link}ы еще не побеждены.]=],
		},
		{
			title = "Вождь племени Камнедробов",
			hint = "Нанесите удар по предводителю восстания троггов.",
			text = [=[{link:nak}Нак{/link}онец его разведчики узнали, кто ведет восстание. {link:troggs}Трогги{/link} шли за вождем {link:grawmug}Гравмуг{/link}ом, который никуда не ходил без двух своих самых свирепых стражей — Скрежетуна и Драчуна. Ругельфусс хотел смерти всех троих. Без вожаков, рассудил он, троггов, быть может, наконец удастся загнать обратно под землю.]=],
		},
		{
			title = "Павшее знамя",
			hint = "Узнайте, что сталось с горным пехотинцем Ильвой.",
			text = [=[{link:mountaineer-ylva}Горный пехотинец Ильва{/link} ушла одна в земли {link:troggs}трогг{/link}ов искать дозор, который так и не вернулся домой. Ее нашли мертвой рядом с растоптанным знаменем {link:ironforge}Стальгорн{/link}а. Когда знамя подняли вновь, трогг, убивший ее, вышел ему навстречу и умер. Ругельфусс забрал знамя, чтобы его вычистили и повесили в башне. Ильва никогда не отличалась осторожностью, сказал он. Теперь они хотя бы знают.]=],
		},
	},
	mentions = {
		{ text = "Угроза {link:troggs}трогг{/link}ов" },
		{
			text = [=[В защиту королевских земель, охота на вождя {link:grawmug}Гравмуг{/link}а]=],
		},
		{
			text = [=[В защиту королевских земель, приказ через пехотинца Кремнебоя]=],
		},
		{ text = "Знамя павших" },
		{ text = "Снабжение фронта, оружие для его горных пехотинцев" },
	},
	bonds = {
		{ id = "mountaineer-cobbleflint", name = "Горный пехотинец Кремнебой", note = "служит в его башне" },
		{ id = "grawmug", name = "Гравмуг", note = "вождь, чьей смерти он хочет" },
		{ id = "mountaineer-ylva", name = "Горный пехотинец Ильва", note = "пала в землях троггов" },
		{ id = "headsplitter", name = "Головолом", note = "убил пехотинца Ильву" },
		{ id = "magni-bronzebeard", name = "Магни Бронзобород", note = "его король" },
	},
})

Translate("ruRU", "chief-engineer-hinderweir-vii", {
	title = "Главный инженер Хиндервейр VII",
	subtitle = "Хранитель Каменной Плотины",
	found = "Наверху Каменной Плотины",
	hint = [=[Поговорите с главным инженером, который несет дозор над плотиной.]=],
	allegiance = "Королевство Стальгорн",
	aliases = { "Хиндервейр" },
	sections = {
		{
			title = "Обзор",
			text = [=[Главный инженер Хиндервейр VII хранит Каменную Плотину, великую каменную стену, которая сдерживает озеро. Он седьмой носитель своего имени, занимающий эту должность, и ни одна летопись не говорит о шести прежних. Это встревоженный {link:dwarves}дворф{/link}, и у него есть на то причина. Его лучшего смотрителя и большую часть стражи отправили на фронт {link:alliance}Альянс{/link}а, а на севере зашевелились дворфы Черного Железа.]=],
		},
		{
			title = "Значение",
			text = [=[Хиндервейр видит закономерность, которой другие не замечают. Сначала был разрушен {link:thandol-span}Мост Тандола{/link}, затем разграблен {link:dun-modr}Дун Модр{/link}. Он не сомневается, что плотина — следующая цель клана Черного Железа, и если она падет, озерный край падет вместе с ней.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он несет дозор над Каменной Плотиной с поредевшей стражей.
• Он посылает образец порошка Черного Железа знатоку взрывчатки в {link:dun-modr}Дун Модр{/link}.
• Он готовит смесь, которая спасает плотину от заряда Черного Железа.]=],
		},
	},
	chapters = {
		{
			title = "След на скате",
			hint = [=[Обыщите восточный скат плотины в поисках следов дворфов Черного Железа.]=],
			text = [=[Саперов Черного Железа видели на восточном скате плотины. Среди того, что они оставили, был бочонок со странно пахнущим порошком. Хиндервейр счел его какой-то взрывчаткой и отправил образец на север через Врата Альгаза — к мастеру пороха полка в {link:dun-modr}Дун Модр{/link}е, {link:ashlan-stonesmirk}Ашлан{/link}у Каменной Усмешке, — с наказом держаться дорог.]=],
		},
		{
			title = "Сефорий",
			hint = "Узнайте, что такое порошок Черного Железа на самом деле.",
			text = [=[Каменная Усмешка узнал порошок по серебристым кристаллам и по запаху: сефорий. Сухой, он безвреден. Мокрый, он способен разорвать гору на части. Он прислал обезвреживающий коллоид и весть о том, что еще нужно: яд пауков-скрытней с холмов, слеза кроколиска и редкий кристалл из тех, что добывают {link:mo-grosh-ogres}огры Мо'грош{/link}.]=],
		},
		{
			title = "Под плотиной",
			hint = "Спасите Каменную Плотину.",
			text = [=[Смесь еще не была готова, когда Хиндервейр увидел, как мятежники Черного Железа плывут к плотине с {link:ogres}огр{/link}омным бочонком, а рядом нет ни одного горного пехотинца, чтобы их остановить. Заряд лежал у подножия плотины, под водой, и смесь успели в него вмешать вовремя. Плотина была спасена. Хиндервейр не делал вида, что она спасена навсегда.]=],
		},
	},
	mentions = {
		{ text = "Нависла темная угроза, саперы на скате" },
		{ text = "Нависла темная угроза, странный порошок" },
		{
			text = [=[Нависла темная угроза, дорога в {link:dun-modr}Дун Модр{/link}]=],
		},
		{ text = "Нависла темная угроза, обезвреживающий коллоид" },
		{ text = "Нависла темная угроза, три составные части" },
		{ text = "Нависла темная угроза, бочонок под водой" },
		{ text = "Нависла темная угроза, плотина спасена" },
	},
	bonds = {
		{ id = "ashlan-stonesmirk", name = "Ашлан Каменная Усмешка", note = "знаток взрывчатки из Дун Модра" },
		{ id = "chok-sul", name = "Чок'сул", note = "его огры владеют кристаллами" },
	},
})

Translate("ruRU", "prospector-ironband", {
	title = "Геолог Сталекрут",
	subtitle = "Геолог Лиги исследователей",
	found = "Раскопки Сталекрута",
	hint = "Найдите геолога, чьи раскопки лежат к юго-востоку от озера.",
	allegiance = "Лига исследователей",
	aliases = { "Сталекрут", "Дартеус Сталекрут" },
	sections = {
		{
			title = "Обзор",
			text = [=[Геолог Дартеус Сталекрут руководит раскопками {link:explorers-league}Лиги исследователей{/link} среди древних руин к юго-востоку от озера. Он крепок, честен и ценит результат. В последнее время результатов у него мало. {link:stonesplinter-troggs}Трогги Камнедробов{/link} захватили его раскопки, взрывной порошок до него никак не доходит, а один из его собратьев-геологов на юге замолчал.]=],
		},
		{
			title = "Значение",
			text = [=[Сталекрут — ученый в поле. Он верит, что резные идолы его раскопок могут раскрыть связь между {link:troggs}трогг{/link}ами и титанами, и идет за этим вопросом от {link:loch-modan}Лок Модан{/link}а до {link:badlands}Бесплодных земель{/link}. То, что он узнаёт, доходит до Лиги в {link:ironforge}Стальгорне{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он руководит раскопками и пишет о них отчеты для Лиги.
• Он снова и снова просит взрывной порошок, который отправляют и который никак не приходит.
• Он посылает за вестями о геологе Эгмонде, который вел раскопки Лиги в Бесплодных землях.]=],
		},
	},
	chapters = {
		{
			title = "Резные идолы",
			hint = "Отнесите отчет геолога в Телсамар.",
			text = [=[Отчет Сталекрута краток и терпелив. Раскопки продолжаются, их замедляют {link:troggs}трогг{/link}и, более злобные, чем обычно. Большинство находок любопытны, и не более. Одна — иное дело: резные идолы притягивают к себе троггов, а некоторых приводят в неистовство. Нужно изучать дальше. И, в который раз, где его взрывной порошок?]=],
		},
		{
			title = "Пропавший порошок",
			hint = "Проследите, чтобы порошок благополучно добрался до раскопок.",
			text = [=[{link:jern-hornhelm}Джерн Рогатый Шлем{/link} послал порошок еще несколько недель назад, и тот так и не дошел. Следующий груз понесли носильщики вдоль изгиба озера, и на дороге ударили {link:dwarves}дворф{/link}ы Черного Железа. Один из носильщиков, Сэан, служил им, хотя проработал бок о бок с остальными почти год. Когда Миран наконец донес остаток порошка, Сталекрут был ему рад — и встревожен тем, что у клана Черного Железа есть друзья, способные наложить руку на такие вещи.]=],
		},
		{
			title = "Участь геолога Эгмонда",
			hint = "Узнайте, что постигло геолога Эгмонда в Бесплодных землях.",
			text = [=[Тело Эгмонда нашли в Бесплодных землях — изломанное и обглоданное дочиста, и рядом единственное слово, нацарапанное на песчанике его рукой: {link:murdaloc}Мурдалок{/link}. Сталекрут оплакал его как бойца с крепким черепом и тяжелым ударом. Он боялся, что урны, найденные его землекопами, разбудили {link:troggs}трогг{/link}ов — так же, как его собственные идолы.]=],
		},
	},
	mentions = {
		{ text = "Отчет о ходе раскопок" },
		{ text = "Порошок для геолога Сталекрута" },
		{ text = "Защита груза" },
		{ text = "Инструменты для раскопок, возвращенные из руин" },
		{ text = "Вы нужны геологу Сталекруту!" },
		{ text = "Найти геолога Эгмонда" },
		{ text = "{link:murdaloc}Мурдалок{/link}" },
		{ text = "Участь геолога Эгмонда" },
	},
	bonds = {
		{ id = "magmar-fellhew", name = "Магмар Лесоруб", note = "заведует его раскопками" },
		{ id = "jern-hornhelm", name = "Джерн Рогатый Шлем", note = "его связной в Телсамаре" },
		{ id = "prospector-stormpike", name = "Геолог Штормпайк", note = "шлет ему помощь из Стальгорна" },
		{ id = "stonesplinter-troggs", name = "Трогги Камнедробов", note = "удерживают его раскопки" },
	},
})

Translate("ruRU", "magistrate-bluntnose", {
	title = "Магистрат Тупонос",
	subtitle = "Магистрат Телсамара",
	found = "Телсамар",
	hint = "Поговорите с магистратом, который управляет Телсамаром.",
	allegiance = "Телсамар · Королевство Стальгорн",
	aliases = { "Тупонос" },
	sections = {
		{
			title = "Обзор",
			text = [=[Магистрат Тупонос управляет {link:thelsamar}Телсамар{/link}ом, и его терпение к {link:ironforge}Стальгорн{/link}у на исходе. Два месяца ушло на то, чтобы услышать, что городку выделят несколько солдат, и ему сказали, что пройдет еще два, прежде чем они прибудут. А тем временем Телсамар, раскопки и плотина открыты для нападения.]=],
		},
		{
			title = "Значение",
			text = [=[Тупонос — голос простого люда озерного края. Там, где капитаны просят солдат, которые так и не приходят, магистрат запускает руку в городскую казну и нанимает всякого, кто готов сражаться. Через него оборона {link:loch-modan}Лок Модан{/link}а переходит в руки чужаков.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он нанимает наемные мечи против {link:ogres}огр{/link}ов {link:mo-grosh-ogres}Мо'грош{/link} на северо-востоке.
• Он назначает награду за голову огра {link:chok-sul}Чок'сул{/link}а, который, как он полагает, ведет нападения на его городок.
• Он намерен взяться за {link:troggs}трогг{/link}ов, как только будет покончено с ограми.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О жизни магистрата до его должности написано мало. Эта запись хранит лишь то, что открывают его городок и его приказы.]=],
		},
	},
	chapters = {
		{
			title = "Наемные руки",
			hint = [=[Возьмите монету магистрата и сразитесь с ограми северо-востока.]=],
			text = [=[{link:ogres}Огры{/link} встали лагерем на северо-восточном берегу озера, и послать против них было некого. Тогда Тупонос послал чужаков. Когда они вернулись с вестью об убитых ограх, он был в восторге. Теперь, когда огры усмирены, сказал он, городок сможет наконец взяться за {link:troggs}трогг{/link}ов.]=],
		},
		{
			title = "Голова огра Чок'сула",
			hint = [=[Откликнитесь на объявление о розыске, которое висит в Телсамаре.]=],
			text = [=[В {link:thelsamar}Телсамар{/link}е висит объявление под печатью магистрата. Оно называет имя — {link:chok-sul}Чок'сул{/link}, {link:ogres}огр{/link}, который, как считают, ведет и замышляет набеги на городок, плотину и раскопки, — и сулит монету за доказательство его смерти. Когда это доказательство положили перед ним, Тупонос отшатнулся при виде его, а потом охотно заплатил.]=],
		},
	},
	mentions = {
		{ text = "Наемники" },
		{ text = "РАЗЫСКИВАЕТСЯ: {link:chok-sul}Чок'сул{/link}" },
	},
	bonds = {
		{ id = "chok-sul", name = "Чок'сул", note = "огр, чьей смерти он хочет" },
		{ id = "mountaineer-kadrell", name = "Горный пехотинец Кадрелл", note = "стережет дорогу через его городок" },
	},
})

Translate("ruRU", "mountaineer-cobbleflint", {
	title = "Горный пехотинец Кремнебой",
	subtitle = "Горный пехотинец южной башни",
