		{ id = "stonesplinter-troggs", name = "Трогги Камнедробов", note = "его враги" },
	},
})

Translate("ruRU", "mountaineer-kadrell", {
	title = "Горный пехотинец Кадрелл",
	subtitle = "Горный пехотинец Телсамара",
	found = "На дороге через Телсамар",
	hint = [=[Ищите горного пехотинца, который обходит дорогу через Телсамар.]=],
	allegiance = "Горные пехотинцы Стальгорна",
	aliases = { "Кадрелл" },
	sections = {
		{
