Translate("ruRU", "stonesplinter-troggs", {
	title = "Трогги Камнедробов",
	aliases = { "Камнедробы", "трогги Камнедробов", "племя Камнедробов" },
	sections = {
		{
			title = "Обзор",
			text = [=[Камнедробы — {link:troggs}трогги{/link} {link:loch-modan}Лок Модан{/link}а. Они носят имя Долины Камнедробов на юго-западе, и это величайшая опасность, перед которой стоит озерный край. Ни одна летопись не говорит, когда они впервые поднялись здесь из глубин.]=],
		},
		{
			title = "Их земли",
			text = [=[Они удерживают Долину Камнедробов и южные холмы, где их вождь {link:grawmug}Гравмуг{/link} занимает самую глубокую пещеру. Они захватили самый большой остров озера. На Раскопках {link:prospector-ironband}Сталекрут{/link}а, где они вышли на поверхность среди руин, раскопом правят вождь Галгош и племенной шаман Магош. В их рядах есть разведчики, черепобои и костоломы, а также провидцы, шаманы и геоманты, которые творят грубую магию земли.]=],
		},
		{
			title = "Наши дни",
			text = [=[Троггов Камнедробов притягивают резные идолы раскопок, и некоторых из них идолы приводят в неистовство. {link:prospector-ironband}Геолог Сталекрут{/link} надеется, что однажды идолы объяснят связь между {link:troggs}трогг{/link}ами и титанами. А пока горные пехотинцы южной башни сражаются с ними тем немногим, что у них есть. Убитых троггов они считают по каменным зубам.]=],
		},
	},
})

Translate("ruRU", "mo-grosh-ogres", {
	title = "Огры Мо'грош",
	aliases = { "Мо'грош", "огры Мо'грош", "клан Мо'грош" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мо'грош — клан {link:ogres}огров{/link}, который устроил свой дом в пещерах Оплота Мо'грош, на северо-востоке {link:loch-modan}Лок Модан{/link}а. Ни одна летопись не говорит, откуда они пришли и когда там поселились.]=],
		},
		{
			title = "Их обычаи",
			text = [=[Среди них есть громилы, каратели и шаманы, есть и мистики, и идут они за вождем {link:chok-sul}Чок'сул{/link}ом. В своих пещерах они добывают кристаллы, столь редкие, что {link:dwarves}дворф{/link}ам приходится сражаться за один-единственный. Они совершают набеги на дороги озерного края, и их винят в нападениях на {link:thelsamar}Телсамар{/link}, Каменную Плотину и раскопки. Однажды они напали из засады на караван с рудой, шедший в Телсамар из {link:wetlands}Болотины{/link}, и унесли руду в свой лагерь.]=],
		},
		{
			title = "Наши дни",
			text = [=[Магистрат {link:thelsamar}Телсамар{/link}а нанял наемные мечи, чтобы сломить их, и над головой их вождя висит награда. Магистрат хочет, чтобы сперва покончили с {link:ogres}огр{/link}ами, и тогда городок сможет наконец взяться за {link:troggs}трогг{/link}ов.]=],
		},
	},
})

Translate("ruRU", "tunnel-rat-kobolds", {
	title = "Кобольды Туннельной Крысы",
	aliases = { "Туннельные Крысы", "кобольды Туннельной Крысы", "кобольды племени Туннельной Крысы" },
